'use strict';

import { environmentFactory } from "./environments/environment.variables.module";
import { CommunicationService } from "./Communication.service";
import localForage from 'localforage';

/**
 * COR Authentication Service.
 * 
 * This class is intended to provide an isolate support for COR API comunication.
 *
 * @export
 * @class CorAuthService
 */
export class CorAuthService extends CommunicationService {

    /**
     * Creates an instance of CorAuthService.
     * @param {Object} Config Object for basic config. This should include user code or any other neccesary options. 
     * @memberof CorAuthService
     */
     constructor(Config = {}) {
        super();

        this.config = {};
        this.environment = Config.environment || environmentFactory();
        this.auth_code = Config.auth_code || null
        
        if (Config.merge !== undefined) {
            this.config = Config.merge('cor-auth-service', {
                environment: this.environment,
                auth_code: this.auth_code
            })
        }

        this.access_token = {
            token: null,
            refresh_token: null,
            expirationTime: null
        };
        
        this.initiateBaseURL();
        this.initiateAccessToken();
       

    }

    /**
     * Get Config
     *
     * @memberof CorAuthService
     */
    get config() {
        return this._config;
    }

    /**
     * Set Config
     * 
     * @param {Object} config
     * @memberof CorAuthService
     */
    set config(config) {
        this._config = Object.assign({}, config);
    }

    /**
     * Set Authorization Code
     * 
     * @param {String} auth_code
     * @memberof CorIntegration
     */
    set auth_code(auth_code) {
        this._config.auth_code = auth_code;
        if (auth_code){
            this.savePermission();
        }
    }

    /**
     * Get Authorization Code
     * 
     * @returns {String}
     * @memberof CorIntegration
     */
    get auth_code() {
        return this._config.auth_code || null;
    }

    /**
     * Set source URL
     * 
     * @param {Object} sourceURLs
     * @memberof CorIntegration
     */
    set environment(environment) {
        this._config.environment = Object.assign({}, environment);
    }

    /**
     * Get source URL
     * 
     * @returns {Object}
     * @memberof CorIntegration
     */
    get environment() {
        return this._config.environment || {};
    }

    /**
     * Set Token
     *
     * @returns {String}
     * @memberof CorIntegration
     */
    set token(token) {
        return this.access_token.token = token;
    }

    /**
     * Get Token
     *
     * @returns {Object}
     * @memberof CorIntegration
     */
    get token() {
        return this.access_token.token || null;
    }

    /**
     * Set expiration time
     *
     * @returns {String}
     * @memberof CorIntegration
     */
    set expirationTime(expirationTime) {
        return this.access_token.expirationTime = expirationTime || (parseInt(new Date().getTime()) + 3600) ;
    }

    /**
     * Get expiration time
     *
     * @returns {Object}
     * @memberof CorIntegration
     */
    get expirationTime() {
        return this.access_token.expirationTime || new Date().getTime();
    }

    /**
     * Set refreshToken
     *
     * @returns {String}
     * @memberof CorIntegration
     */
    set refresh_token(refresh_token) {
        return this.access_token.refresh_token = refresh_token;
    }

    /**
     * Get refreshToken
     *
     * @returns {Object}
     * @memberof CorIntegration
     */
    get refresh_token() {
        return this.access_token.refresh_token || null;
    }

    /**
     * Set permissions
     * 
     * @returns {Object}
     */
    set permissions(permissions){
        
        if (permissions != undefined){
            
            localForage.setItem('permissions', permissions)
            .then(() => this.permission_state = true)
            .catch(() => this.permission_state = false);
            
        }
        
    }

    /**
     * Get permissions
     * 
     * @returns {Object}
     */
    get permissions(){
        return localForage.getItem('permissions')
    }


    __checkService(){
        if (this.environment.apiEndpoint != undefined){
            return this.get(this.environment.apiEndpoint)
        }else{
            return Promise.reject(new Error(`There isn't a configured environment`));
        }
    }

    /**
     * Initialize the token from the local Forage
     */
    async initiateAccessToken(){
        let self = this;
        self.initiateHeaderAuth(self.token);
        await localForage.getItem('token')
            .then(value => {
                if (value){
                    self.token = value.token || null;
                    self.refresh_token = value.refresh_token || null;
                    self.expirationTime = value.expirationTime || null;
                    self.initiateHeaderAuth(self.token);
                    // self.savePermission();
                }
            })
    }

    /**
     * Check that the token exists and its expiration time
     * @return {boolean}
     */
    checkToken(){

        let lapsed_time = ((new Date().getTime()) - this.expirationTime)/ 1000;
       
        if (this.token && lapsed_time < 3600){
            return true;
        }else {
            return false;
        }
    }


    /**
     * Make a API request for generate the users token
     * @return {Promise<any>}
     */
    async generateToken(){

        const self = this;
        
        return new Promise((resolve, reject) => {
            self.post('v1/oauth2/token', {grant_type : 'authorization_code', code : self.auth_code})
                .then(async (res) => {
                    
                    let token = {
                        refresh_token : res.refresh_token,
                        token : res.access_token,
                        expirationTime : res.expirationTime || (parseInt(new Date().getTime())+ 3600000)
                    }

                    //Save the generated token
                    await localForage.setItem('token', token)
                        .then( value =>{
                            self.token = value.token;
                            self.refresh_token = value.refresh_token;
                            self.expirationTime = value.expirationTime;
                        });

                    resolve(res);
                }).catch((err) => {
                    reject(err);
                });

        });
    }

    /**
     * Regenerate the users token
     * @return {Promise<any>}
     */
    async refreshToken(){

        const self = this;

        return new Promise((resolve, reject) => {
            self.post('v1/oauth/refreshToken', {refresh_token : self.refresh_token})
                .then(async(res) => {

                    let token = {
                        refresh_token : res.token.refreshToken,
                        token : res.token.access_token,
                        expirationTime : res.token.expirationTime || (parseInt(new Date().getTime())+ 3600000)
                    }

                    //Save the generated token
                    await localForage.setItem('token', token)
                        .then( value =>{
                            self.token = value.token;
                            self.refresh_token = value.refresh_token;
                            self.expirationTime = value.expirationTime;
                        });

                    resolve(res);
                }).catch((err) => {
                    reject(err)
                });

        });
    }


    /**
     * Get permission from API and save permissions.
     */
    async savePermission(){
        if (this.checkToken()){
            await this.get('v1/me')
            .then(result =>{
                this.permissions = result && result.permissions && result.permissions.permissions ? result.permissions.permissions : null;
                return Promise.resolve(result)
            })
            .catch(err => {
                return Promise.reject(err)
            });
        }        
    }

    /**
     * Check user permissions as per entity.
     *
     * @param {String} entity
     * @param {String} type
     * @returns {Boolean}
     * @memberof CorAuthService
     */
    async checkPermissions(entity, type){
        let permissions = await this.permissions
        return permissions[entity] != undefined && permissions[entity][type] != undefined && permissions[entity][type];
    }
}

const CorApiService = new CorAuthService();

export default CorApiService;